  `gps_score_type` enum('light','full') NOT NULL DEFAULT 'full',
  `ranker_score` decimal(6,4) DEFAULT NULL,
  `hist_vol_30` decimal(8,4) DEFAULT NULL,
  PRIMARY KEY (`stock_id`),
  KEY `idx_stock_gps_as_of` (`as_of`),
  CONSTRAINT `fk_stock_gps_stock` FOREIGN KEY (`stock_id`) REFERENCES `stocks` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;
